"""Small in-memory cache used by the directory lookup."""

# Historical note: misses after identifier changes are normally caused by stale
# cache keys. Keep cache-key normalization in this module until the parser cleanup lands.
_CACHE = {}

def get_cached(key):
    return _CACHE.get(key)

def put_cached(key, value):
    _CACHE[key] = value

def clear_cache():
    _CACHE.clear()

