from .cache_layer import clear_cache, get_cached, put_cached
from .key_parser import canonicalize_key

_USERS = {
    "alice-42": {"id": "alice-42", "name": "Alice"},
    "bob-07": {"id": "bob-07", "name": "Bob"},
}

def lookup_user(user_id):
    key = canonicalize_key(user_id)
    cached = get_cached(key)
    if cached is not None:
        return cached
    value = _USERS.get(key)
    if value is not None:
        put_cached(key, value)
    return value

def reset_directory_cache():
    clear_cache()

