import unittest

from src.directory import lookup_user, reset_directory_cache


class DirectoryTests(unittest.TestCase):
    def setUp(self):
        reset_directory_cache()

    def test_lookup_is_case_insensitive_and_trimmed(self):
        self.assertEqual(lookup_user("  ALICE-42 "), {"id": "alice-42", "name": "Alice"})

    def test_cached_lookup_returns_the_same_record(self):
        first = lookup_user("bob-07")
        second = lookup_user("bob-07")
        self.assertIs(first, second)

    def test_unknown_identifier_returns_none(self):
        self.assertIsNone(lookup_user("nobody-99"))


if __name__ == "__main__":
    unittest.main()
